#include <stdio.h>

unsigned long djb2(char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) hash = ((hash << 5) + hash) + c;
    return hash;
}

int main() {
    printf("hello: %lu\n", djb2("hello"));
    printf("world: %lu\n", djb2("world"));
    printf("hello: %lu\n", djb2("hello"));
    return 0;
}
